import type { SidebarsConfig } from '@docusaurus/plugin-content-docs';

// This runs in Node.js - Don't use client-side code here (browser APIs, JSX...)

/**
 * Creating a sidebar enables you to:
 - create an ordered group of docs
 - render a sidebar for each doc of that group
 - provide next/previous navigation

 The sidebars can be generated from the filesystem, or explicitly defined here.

 Create as many sidebars as you want.
 */
// The OpenAPI sidebar slices are generated by `docusaurus-plugin-openapi-docs` into `docs/combine-api/` and `docs/cap-scap-api/` and won't exist on a fresh checkout
const loadApiItems = (outputDir: string): SidebarsConfig[string] => {
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    return require(`./docs/${outputDir}/sidebar`).default;
  } catch {
    return [];
  }
};

// API reference nested underneath it as a sub-category.
const combineAwsItems: SidebarsConfig[string] = [
  { type: 'autogenerated', dirName: 'Combine-AWS' },
];

const addApiCategory = (outputDir: string, label: string, description: string): void => {
  const apiItems = loadApiItems(outputDir);

  if (Array.isArray(apiItems) && apiItems.length > 0) {
    combineAwsItems.push({
      type: 'category',
      label,
      link: {
        type: 'generated-index',
        title: label,
        description,
      },
      items: apiItems,
    });
  }
};

addApiCategory('combine-api', 'Combine API', 'Reference for the Combine TAP API.');
addApiCategory('cap-scap-api', 'CAP / SCAP API', 'Reference for the CAP / SCAP compatible credential API.');

const sidebars: SidebarsConfig = {
  tutorialSidebar: [
    {
      type: 'category',
      label: 'Combine AWS',
      items: combineAwsItems,
    },
    {
      type: 'category',
      label: 'Combine Azure',
      items: [{ type: 'autogenerated', dirName: 'Combine-Azure' }],
    },
  ],
};

export default sidebars;
